mapper.select:
SELECT r.id AS id, r.code AS code, a.name AS appName, p.name AS pipelineName, r.branch AS branch, r.ref_value AS refValue, r.status AS status, r.start_time AS startTime, r.end_time AS endTime, r.create_time AS createTime FROM dev_run r LEFT JOIN dev_pipeline p ON p.id = r.pipeline_id AND p.is_deleted = 0 LEFT JOIN dev_app a ON a.id = r.app_id AND a.is_deleted = 0
r.is_deleted = 0
AND (r.code LIKE CONCAT('%', #{query.keyword}, '%') OR a.name LIKE CONCAT('%', #{query.keyword}, '%') OR p.name LIKE CONCAT('%', #{query.keyword}, '%'))
AND r.app_id = #{query.appId}
AND r.pipeline_id = #{query.pipelineId}
AND r.status IN
#{status}
ORDER BY r.create_time DESC, r.id DESC
